#!/usr/bin/env python3
"""Convert the mybd generated HTML reports (headings, .cards, .meta/.summary/.filters divs, tables) to Markdown."""
import sys
from html.parser import HTMLParser


class MD(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out = []          # finished markdown blocks
        self.buf = []          # inline text accumulator
        self.stack = []        # open tag names
        self.href = None
        self.in_table = False
        self.rows = []
        self.row = []
        self.cell = []
        self.header_done = False
        self.skip = 0          # inside style/script/head
        self.card_num = None
        self.in_cards = False
        self.classes = {}

    def flush_para(self):
        text = "".join(self.buf).strip()
        self.buf = []
        if text:
            self.out.append(text + "\n")

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        cls = a.get("class", "")
        if tag in ("style", "script", "head"):
            self.skip += 1
            return
        if self.skip:
            return
        if tag in ("h1", "h2", "h3"):
            self.flush_para()
            self.buf.append("#" * int(tag[1]) + " ")
        elif tag == "div":
            if "cards" in cls.split():
                self.flush_para()
                self.in_cards = True
            elif self.in_cards and "card" in cls.split():
                self.card_parts = []
            elif self.in_table and "muted" in cls.split():
                self.cell.append(" — ")
            elif not self.in_table and cls in ("meta", "summary", "filters"):
                self.flush_para()
            self.stack.append((tag, cls))
        elif tag == "a":
            self.href = a.get("href")
            (self.cell if self.in_table else self.buf).append("[")
        elif tag == "code":
            (self.cell if self.in_table else self.buf).append("`")
        elif tag == "strong":
            (self.cell if self.in_table else self.buf).append("**")
        elif tag == "table":
            self.flush_para()
            self.in_table = True
            self.rows = []
        elif tag == "tr":
            self.row = []
        elif tag in ("td", "th"):
            self.cell = []
        elif tag == "br":
            (self.cell if self.in_table else self.buf).append(" ")

    def handle_endtag(self, tag):
        if tag in ("style", "script", "head"):
            self.skip -= 1
            return
        if self.skip:
            return
        if tag in ("h1", "h2", "h3"):
            self.flush_para()
        elif tag == "div":
            if self.stack and self.stack[-1][0] == "div":
                _, cls = self.stack.pop()
                if "cards" in cls.split() and self.in_cards:
                    self.in_cards = False
                    self.flush_para()
                elif self.in_cards and "card" in cls.split():
                    text = "".join(self.buf).strip()
                    self.buf = []
                    parts = text.split(None, 1)
                    if len(parts) == 2:
                        self.out.append(f"- **{parts[0]}** {parts[1]}\n")
                    elif text:
                        self.out.append(f"- {text}\n")
                elif not self.in_table and cls in ("meta", "summary", "filters"):
                    self.flush_para()
        elif tag == "a":
            target = self.cell if self.in_table else self.buf
            target.append(f"]({self.href})")
            self.href = None
        elif tag == "code":
            (self.cell if self.in_table else self.buf).append("`")
        elif tag == "strong":
            (self.cell if self.in_table else self.buf).append("**")
        elif tag in ("td", "th"):
            text = " ".join("".join(self.cell).split())
            self.row.append(text.replace("|", "\\|"))
            self.cell = []
        elif tag == "tr":
            if self.row:
                self.rows.append(self.row)
            self.row = []
        elif tag == "table":
            self.in_table = False
            if self.rows:
                lines = ["| " + " | ".join(self.rows[0]) + " |",
                         "|" + "|".join("---" for _ in self.rows[0]) + "|"]
                for r in self.rows[1:]:
                    lines.append("| " + " | ".join(r) + " |")
                self.out.append("\n".join(lines) + "\n")
            self.rows = []
        elif tag == "main":
            self.flush_para()

    def handle_data(self, data):
        if self.skip:
            return
        if self.in_table:
            self.cell.append(data)
        else:
            self.buf.append(data.replace("\n", " "))


src, dst = sys.argv[1], sys.argv[2]
p = MD()
p.feed(open(src, encoding="utf-8").read())
p.flush_para()
open(dst, "w", encoding="utf-8").write("\n".join(b.rstrip() + "\n" for b in p.out if b.strip()))
print(f"wrote {dst}")

