#!/usr/bin/env python3
"""Convert the mybd generated HTML reports (headings, stat cards, callout/meta divs, tables, lists) to Markdown."""
import sys
from html.parser import HTMLParser

PARA_CLASSES = {"meta", "summary", "filters", "callout", "sub"}


class MD(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out = []          # finished markdown blocks
        self.buf = []          # inline text accumulator
        self.stack = []        # open (tag, class) for div/section
        self.href = None
        self.in_table = False
        self.rows = []
        self.row = []
        self.cell = []
        self.skip = 0          # inside style/script/head
        self.in_cards = False

    def flush_para(self):
        text = " ".join("".join(self.buf).split())
        self.buf = []
        if text:
            self.out.append(text + "\n")

    def sink(self):
        return self.cell if self.in_table else self.buf

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        cls = set(a.get("class", "").split())
        if tag in ("style", "script", "head"):
            self.skip += 1
            return
        if self.skip:
            return
        if tag in ("h1", "h2", "h3"):
            self.flush_para()
            self.buf.append("#" * int(tag[1]) + " ")
        elif tag in ("div", "section"):
            if "cards" in cls:
                self.flush_para()
                self.in_cards = True
            elif self.in_table:
                if self.cell and "muted" in cls:
                    self.cell.append(" — ")
                elif self.cell:
                    self.cell.append(" ")
            elif self.in_cards and cls & {"num", "metric"}:
                self.buf.append("**")
            elif self.in_cards and "hint" in cls:
                self.buf.append("— ")
            elif cls & PARA_CLASSES:
                self.flush_para()
            self.stack.append((tag, cls))
        elif tag == "li":
            self.flush_para()
            self.buf.append("- ")
        elif tag == "a":
            self.href = a.get("href")
            self.sink().append("[")
        elif tag == "code":
            self.sink().append("`")
        elif tag in ("strong", "b"):
            self.sink().append("**")
        elif tag in ("em", "i"):
            self.sink().append("*")
        elif tag == "table":
            self.flush_para()
            self.in_table = True
            self.rows = []
        elif tag == "tr":
            self.row = []
        elif tag in ("td", "th"):
            self.cell = []
        elif tag == "br":
            self.sink().append(" ")
        elif tag == "p":
            self.flush_para()

    def handle_endtag(self, tag):
        if tag in ("style", "script", "head"):
            self.skip -= 1
            return
        if self.skip:
            return
        if tag in ("h1", "h2", "h3"):
            self.flush_para()
        elif tag in ("div", "section"):
            if self.stack and self.stack[-1][0] == tag:
                _, cls = self.stack.pop()
                if "cards" in cls and self.in_cards:
                    self.in_cards = False
                    self.flush_para()
